{
  "error": {
    "code": "CAPTURE_INVALID_INPUT",
    "message": "The setting pen_width_mm must be 0.1 to 3 mm.",
    "meta": {
      "field": "pen_width_mm",
      "allowed": "0.1 to 3 mm"
    }
  }
}

{
  "error": {
    "code": "CAPTURE_IMAGE_TOO_SMALL",
    "message": "The photo is too small to measure (999 × 750 px). Its long side needs at least 1000 px.",
    "meta": {
      "width": 999,
      "height": 750,
      "min_long_side": 1000
    }
  }
}

{
  "error": {
    "code": "CAPTURE_UNREADABLE_IMAGE",
    "message": "The photo can't be read: it may be damaged or cut short. Please take it again.",
    "meta": {}
  }
}

{
  "error": {
    "code": "CAPTURE_FILE_TOO_LARGE",
    "message": "The photo is too large. Send one of at most 15 MB, as a JPEG.",
    "meta": {
      "max_mb": 15
    }
  }
}

{
  "error": {
    "code": "CAPTURE_IMAGE_TOO_LARGE",
    "message": "The photo has too many pixels (8000 × 5001). Send one of at most 40 megapixels.",
    "meta": {
      "width": 8000,
      "height": 5001,
      "max_megapixels": 40
    }
  }
}

{
  "error": {
    "code": "CAPTURE_UNSUPPORTED_IMAGE",
    "message": "This file isn't a JPEG, PNG or WebP photo. Send the photo as a JPEG.",
    "meta": {}
  }
}

{
  "error": {
    "code": "UNSUPPORTED_MEDIA_TYPE",
    "message": "This type of content isn't accepted here.",
    "meta": {
      "expected": "multipart/form-data"
    }
  }
}

{
  "error": {
    "code": "RATE_LIMITED",
    "message": "Too many requests. Please try again in 1799 s.",
    "meta": {
      "retry_after_seconds": 1799
    }
  }
}

{
  "error": {
    "code": "SERVICE_UNAVAILABLE",
    "message": "The service is unavailable right now. Please try again in a few seconds.",
    "meta": {
      "dependency": "storage"
    }
  }
}
